PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY, name TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic=1));
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY, display_name TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic=1));
CREATE TABLE IF NOT EXISTS organization_memberships(org_id TEXT NOT NULL REFERENCES organizations(id), actor_id TEXT NOT NULL REFERENCES profiles(id), role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(org_id,actor_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, org_id TEXT NOT NULL, actor_id TEXT NOT NULL, expires_at INTEGER NOT NULL, FOREIGN KEY(org_id,actor_id) REFERENCES organization_memberships(org_id,actor_id));
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), kind TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), revision INTEGER NOT NULL DEFAULT 1, access TEXT NOT NULL DEFAULT 'private' CHECK(access IN ('private','chapter')), synthetic INTEGER NOT NULL DEFAULT 1 CHECK(synthetic=1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(org_id,id));
CREATE INDEX IF NOT EXISTS record_scope ON records(org_id,kind);
CREATE TABLE IF NOT EXISTS record_access_assignments(org_id TEXT NOT NULL, record_id TEXT NOT NULL, actor_id TEXT NOT NULL, permission TEXT NOT NULL CHECK(permission IN ('read','write')), PRIMARY KEY(org_id,record_id,actor_id), FOREIGN KEY(org_id,record_id) REFERENCES records(org_id,id), FOREIGN KEY(org_id,actor_id) REFERENCES organization_memberships(org_id,actor_id));
CREATE TABLE IF NOT EXISTS approval_requests(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), action_type TEXT NOT NULL, targets TEXT NOT NULL CHECK(json_valid(targets)), payload TEXT NOT NULL CHECK(json_valid(payload)), payload_hash TEXT NOT NULL, dependencies TEXT NOT NULL CHECK(json_valid(dependencies)), proposer TEXT NOT NULL, approver TEXT, policy_version TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','pending_review','approved','rejected','expired','cancelled','executing','succeeded','failed','outcome_unknown')), created_at TEXT NOT NULL, expires_at TEXT NOT NULL, decided_at TEXT, UNIQUE(org_id,id));
CREATE TABLE IF NOT EXISTS execution_attempts(id TEXT PRIMARY KEY, org_id TEXT NOT NULL, approval_id TEXT NOT NULL UNIQUE, idempotency_key TEXT NOT NULL, payload_hash TEXT NOT NULL, adapter TEXT NOT NULL, status TEXT NOT NULL, result TEXT NOT NULL CHECK(json_valid(result)), created_at TEXT NOT NULL, UNIQUE(org_id,idempotency_key), FOREIGN KEY(org_id,approval_id) REFERENCES approval_requests(org_id,id));
CREATE TABLE IF NOT EXISTS job_queue(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), actor_id TEXT NOT NULL, role TEXT NOT NULL, objective TEXT NOT NULL, context TEXT NOT NULL CHECK(json_valid(context)), status TEXT NOT NULL, output TEXT, error TEXT, created_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE IF NOT EXISTS audit_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, org_id TEXT NOT NULL REFERENCES organizations(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, detail TEXT NOT NULL CHECK(json_valid(detail)), created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit events are append-only'); END;
INSERT OR IGNORE INTO schema_migrations VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
